import{_ as a,o as e,c as i,a2 as l}from"./chunks/framework.CHeM0PsO.js";const r="/images/misskey-themes.webp",m=JSON.parse('{"title":"界面、主题与小工具","description":"","frontmatter":{},"headers":[],"relativePath":"guide/misskey/ui-themes.md","filePath":"guide/misskey/ui-themes.md","lastUpdated":1793076233000}'),d={name:"guide/misskey/ui-themes.md"};function s(o,t,h,n,c,u){return e(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="界面、主题与小工具" tabindex="-1">界面、主题与小工具 <a class="header-anchor" href="#界面、主题与小工具" aria-label="Permalink to &quot;界面、主题与小工具&quot;">​</a></h1><h2 id="界面模式" tabindex="-1">界面模式 <a class="header-anchor" href="#界面模式" aria-label="Permalink to &quot;界面模式&quot;">​</a></h2><p>Misskey 提供两种整体界面布局，在侧栏菜单「切换界面」中选择：</p><ul><li><strong>默认界面</strong>：单列时间线 + 右侧信息栏，适合日常浏览。</li><li><strong>Deck</strong>：多栏布局，可把首页时间线、列表、天线、通知等多个「列」并排常驻，像专业客户端一样一屏监控多路信息。列可以自由添加、排列、调整宽度。</li></ul><p>手机等窄屏下会自动切换为移动端布局。</p><h2 id="主题" tabindex="-1">主题 <a class="header-anchor" href="#主题" aria-label="Permalink to &quot;主题&quot;">​</a></h2><ul><li>在「设置 → 主题」可以切换内置主题，本站默认为深色风格。</li><li>浅色、深色主题分别选择，可跟随系统自动切换。</li><li>支持自定义主题：用主题编辑器调整背景、强调色等，也可以通过「安装主题」粘贴他人分享的主题代码，在「管理主题」中删除。</li></ul><p><img src="'+r+'" alt="主题设置"></p><h2 id="小工具" tabindex="-1">小工具 <a class="header-anchor" href="#小工具" aria-label="Permalink to &quot;小工具&quot;">​</a></h2><p>默认界面右侧栏（Deck 中为「小工具」列）可以放置小工具，进入编辑模式后添加、拖拽排列、单独配置。</p><table tabindex="0"><thead><tr><th>分类</th><th>小工具</th></tr></thead><tbody><tr><td>个人与社交</td><td>个人资料、通知、时间线、用户列表、私信、发帖窗口、今天是他们的生日、在线用户数</td></tr><tr><td>信息</td><td>服务器信息、趋势、活动、照片、RSS 阅读器、RSS Ticker、幻灯片展示</td></tr><tr><td>时间</td><td>日历、时钟、数字时钟、UNIX 时钟</td></tr><tr><td>工具与娱乐</td><td>便利贴、按钮、AiScript 控制台、AiScript App、小蓝、点击器</td></tr><tr><td>服务器状态</td><td>服务器指标、作业队列</td></tr></tbody></table><h2 id="导航栏与状态栏" tabindex="-1">导航栏与状态栏 <a class="header-anchor" href="#导航栏与状态栏" aria-label="Permalink to &quot;导航栏与状态栏&quot;">​</a></h2><ul><li>「设置 → 导航栏」：调整左侧菜单显示哪些项目及顺序，可选完整显示或仅图标。可添加的项目还包括：查询（输入帖子或用户地址直接打开）、二维码（显示自己的二维码或扫码）、工具（草稿本、API Console、点击器）、重新加载、清除缓存等。</li><li>「设置 → 状态栏」：在页面顶部或底部常驻显示 RSS、用户列表动态等滚动信息。</li></ul><h2 id="声音与插件" tabindex="-1">声音与插件 <a class="header-anchor" href="#声音与插件" aria-label="Permalink to &quot;声音与插件&quot;">​</a></h2><ul><li>「设置 → 声音」：为通知、回应等事件设置提示音。</li><li>「设置 → 插件」：安装 AiScript 插件扩展客户端功能（如自定义发帖后操作）。</li><li>「设置 → 表情符号调色板」：自定义回应和发帖时弹出的表情面板。</li><li>「设置 → 自定义 CSS」（高级）：注入自定义样式微调界面。</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>自定义 CSS 和插件属于高级功能，安装来源不明的插件有风险，只添加可信的内容。</p></div>',16)])])}const _=a(d,[["render",s]]);export{m as __pageData,_ as default};
